//! Actions-only actual Router/TLS/Common poll guard and partial-ciphertext Join.
use super::*;
use n::{account_test_support::TempDatabase,buddy_relation_check as check,relation_journal::RelationConfiguration};
fn original(temp:&TempDatabase,root:&str)->(AttemptOwner,Arc<n::account_runs::RunToken>){let line="app-account-0123456789abcdef0123456789abcdef";let mut cfg=n::account_config::tests::native_fixture(root,"127.0.0.1",1);cfg.credentials.sdk.expires_at_unix_seconds=None;cfg.profile.incoming=None;cfg.profile.client_ex=true;cfg.profile.native_receivers=Some(config(true));cfg.profile.buddy_relation_check=Some(check::NativeBuddyRelationCheckConfig{check:true});temp.database.with_conn(|c|n::account_store::create(c,line,&cfg,100)).unwrap();let run=Arc::new(temp.database.with_conn(|c|n::account_runs::register_runtime(c,line,1,&n::account_runtime::local_nonce().unwrap())).unwrap());let mut s=n::session::HostingSession::new(line.into());s.import(n::tests::imported(),100).unwrap();(s.begin_login(100).unwrap(),run)}
async fn check_auth(handle:&RuntimeHandle,events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope){let p=NativeReceiverPolicy::capture(&config(true)).unwrap().with_buddy_relation_check(check::NativeBuddyRelationCheckConfig{check:true}).unwrap();let setup=NativeReceiverSetup::capture(p,true,None).unwrap();let commands=handle.command_handle();commands.arm_native_receivers(who,scope,setup).await.unwrap();authenticated(handle,events,who,scope).await;commands.configure_native_receivers(who,scope,7).await.unwrap();}
fn check_query(temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,who:&AttemptOwner,scope:&RpcConnectionScope,gate:Arc<ImReceiptGate>,end:Instant)->(Arc<ImQuery>,check::CheckWait){let input=scope.reserve_native_rpc(check::input_size(b"1_2").unwrap()).unwrap();let cfg=Arc::new(temp.database.with_conn(|c|RelationConfiguration::capture(c,run.line_id(),run.revision(),Some(scope))).unwrap());let c=check::CheckContext::capture(temp.database.clone(),run,who.clone(),scope.clone(),cfg,gate,end).unwrap();let q=Arc::new(ImQuery::buddy_check(b"1_2",input,end).unwrap()).bind_buddy_context(c.clone()).unwrap();(q.clone(),check::CheckWait(c,q))}
async fn eof(peer:&mut CommonPeer){while let Some(p)=peer.next_input_only().await{assert!(matches!(p.as_slice(),[2]|[14]|[4]),"no retired query or replacement SDK business frame");}}
async fn partial(mode:u8){let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);
 let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;eof(&mut p).await;};
 let client=async{let mut conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let prefix=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original_unarmed(1);n::common_runtime::tests::gate_auxiliary_prefix(conn.common.as_mut().unwrap(),prefix.clone());let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();check_auth(&handle,&mut events,&who,&scope).await;let gate=ImReceiptGate::fresh();let end=Instant::now()+Duration::from_secs(3);let(q,wait)=check_query(&temp,run.clone(),&who,&scope,gate.clone(),end);prefix.arm();let commands=handle.command_handle();let mut op=Box::pin(commands.read_im(&who,&scope,q.clone(),gate.clone()));tokio::select!{r=&mut op=>panic!("partial check returned {r:?}"),_=bounded(prefix.paused())=>{}}assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert!(!prefix.dropped.load(Ordering::SeqCst));
 if mode==0{drop(op);drop(wait);}else if mode==1{gate.retire();assert_eq!(bounded(op).await.err(),Some(RuntimeError::Cancelled));drop(wait);}else{temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();assert!(bounded(op).await.is_err());drop(wait);}
 bounded(scope.closed()).await;let terminal=bounded(handle.close()).await;assert!(terminal.io_released());assert!(prefix.dropped.load(Ordering::SeqCst));assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert!(scope.native_rpc_resources().1>0);drop(q);assert_eq!(scope.native_rpc_resources(),(0,0));assert!(temp.database.get_recent_app_events(Some(run.line_id()),128).unwrap().is_empty());};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));}
#[tokio::test]async fn buddy_check_io_partial_ciphertext_wait_drop_joins_original_fd_without_retry(){Box::pin(partial(0)).await;}
#[tokio::test]async fn buddy_check_io_partial_ciphertext_parent_retirement_blocks_late_bytes(){Box::pin(partial(1)).await;}
#[tokio::test]async fn buddy_check_io_config_change_after_one_ciphertext_byte_stops_same_pinned_write(){Box::pin(partial(2)).await;}
